INSERT INTO rule_master
    (rule_id, judgement_type, room_option, normal_yaku_condition, yakuman_condition, rule_name, rule_detail, evt_sum_type)
VALUES
    (21, 4, '1100000100002', '0000000000000000000000000000', '000000000000000', '和了回数－放銃回数・半荘戦', '半荘戦で「和了った回数」から「放銃した回数」を引いた累積数を競います。<br>※ダブロン、トリロンに振り込んだ場合はそれぞれ放銃回数を２回、３回としてカウントします。', NULL),
    (1, 0, '0110000100002', '0000000110000000000000000000', '000000000000000', '「断幺」「平和」和了回数・東風戦', '東風戦で「断幺九」「平和」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます', NULL),
    (2, 0, '1110000100002', '0000000110000000000000000000', '000000000000000', '「断幺」「平和」和了回数・半荘戦', '半荘戦で「断幺九」「平和」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます', NULL),
    (3, 0, '0110000100002', '0000000100000000000000000000', '000000000000000', '「平和」和了回数・東風戦', '東風戦で「平和」で和了った回数を競います。', NULL),
    (4, 0, '1110000100002', '0000000100000000000000000000', '000000000000000', '「平和」和了回数・半荘戦', '半荘戦で「平和」で和了った回数を競います。', NULL),
    (5, 0, '1110000100002', '0000000000000000000001100000', '000000000000000', '「純全帯幺」「全帯幺」和了回数・半荘戦', '半荘戦で「純全帯幺」「全帯幺」いずれかで和了った回数を競います。', NULL),
    (6, 0, '1110000100002', '0000010001010000000000001100', '000001100000000', '「一」の付く役和了回数・半荘戦', '半荘戦で「一発」「一盃口」「一気通貫」「混一色」「清一色」「字一色」「緑一色」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます', NULL),
    (7, 0, '1110000100002', '0000000000000101011100000000', '100000000000000', '「三」の付く役和了回数・半荘戦', '半荘戦で「三色同順」「三色同刻」「三暗刻」「三槓子」「小三元」「大三元」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます', NULL),
    (8, 0, '1110000100002', '0000000000000101000000000000', '000000000000000', '「三色同順」「三色同刻」和了回数・半荘戦', '半荘戦で「三色同順」「三色同刻」いずれかで和了った回数を競います。', NULL),
    (9, 0, '1110000100002', '0000000000000000000000000000', '111111111111111', '役満和了回数・半荘戦', '半荘戦で「大三元」「四暗刻」「四槓子」「小四喜」「清老頭」「字一色」「緑一色」「九連宝燈」「国士無双」「天和」「地和」「四暗刻単騎」「大四喜」「国士無双13門待ち」「純正九連宝燈」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます<br>※2倍役満は1つとしてカウントします。', NULL),
    (10, 0, '1110000100002', '1110010000000000100000000010', '000000000110000', '偶然性の高い役和了回数・半荘戦', '半荘戦で「一発」「搶槓」「嶺上開花」「天和」「地和」「W立直」「海底」「河底」いずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます', NULL),
    (11, 0, '0110000100002', '0000100000000000000000000010', '000000000000000', '「立直」和了回数・東風戦', '東風戦で「立直」「Ｗ立直」で和了った回数を競います。', NULL),
    (12, 0, '1110000100002', '0000100000000000000000000010', '000000000000000', '「立直」和了回数・半荘戦', '半荘戦で「立直」「Ｗ立直」で和了った回数を競います。', NULL),
    (13, 1, '1110000100002', '0000000000000000000000000000', '000000000000000', '「役牌」和了回数・半荘戦', '半荘戦で「役牌」のいずれかで和了った回数を競います。<br>※同時に達成した場合は別途カウントされます。<br>※また、役満時（大三元など）に使用した役牌はカウントされません。', NULL),
    (14, 2, '1110000100002', '0000000000000000000000000000', '000000000000000', 'ドラ使用枚数・半荘戦', '半荘戦で和了時のドラ使用枚数を競います。<br>※裏ドラ・赤牌・槓ドラ・槓裏もそれぞれカウントされます。', NULL),
    (15, 3, '1110000100002', '0000000000000000000000000000', '000000000000000', '和了回数・半荘戦', '半荘戦でツモ・ロンに関わらず「和了った回数」を競います。', NULL),
    (16, 4, '1110000100002', '0000000000000000000000000000', '000000000000000', '和了回数－放銃回数・半荘戦', '半荘戦で「和了った回数」から「放銃した回数」を引いた累積数を競います。<br>※ダブロン、トリロンに振り込んだ場合はそれぞれ放銃回数を２回、３回としてカウントします。', NULL),
    (17, 5, '1110000100002', '0000000000000000000000000000', '000000000000000', '和了翻数・半荘戦', '半荘戦で和了った役の合計翻数を競います。<br>※シングル役満は13飜、ダブル役満は26飜固定とします。<br>※数え役満に関しては構成役の翻数全てをカウントします。', NULL),
    (18, 6, '1110000100000', '0000000000000000000000000000', '000000000000000', '和了点数１・半荘戦・ワレメ無', '半荘戦で役自体の和了点の合計を競います。', NULL),
    (19, 6, '1110000100100', '0000000000000000000000000000', '000000000000000', '和了点数・半荘戦・ワレメ有', '半荘戦で役自体の和了点の合計を競います。<br>※ワレメ時は和了点を倍にしてカウントします。', NULL),
    (20, 7, '1110000100002', '0000000000000000000000000000', '000000000000000', '飛ばし回数－飛び回数・半荘戦', '半荘戦で自分が相手を「飛ばした回数」から自分が「飛んだ回数」を引いた累積数を競います。<br>※同時に複数人数を飛ばした場合は、その人数分も別途カウントされます。', NULL),
